payload:
$ErrorActionPreference='Stop'
$repo = Join-Path $env:USERPROFILE 'mhw-pr230-validation'
if (Test-Path $repo) { Remove-Item -Recurse -Force $repo }
git clone --quiet https://github.com/fengie/mhw-mods.git $repo
if ($LASTEXITCODE -ne 0) { throw "clone failed $LASTEXITCODE" }
git -C $repo checkout --quiet fix/heaven2-bridge-self-heal-20260929
if ($LASTEXITCODE -ne 0) { throw "checkout failed $LASTEXITCODE" }
Push-Location $repo
try {
  & .\heaven-bridge\manage.ps1 TEST
  if ($LASTEXITCODE -ne 0) { throw "bridge manage TEST failed $LASTEXITCODE" }
  python plugins\heaven-control-plane\verify.py
  if ($LASTEXITCODE -ne 0) { throw "control-plane verify failed $LASTEXITCODE" }
  git diff --check
  if ($LASTEXITCODE -ne 0) { throw "git diff --check failed $LASTEXITCODE" }
  $head=(git rev-parse HEAD).Trim()
  Write-Output "PR230_COMBINED_VALIDATION_OK head=$head"
} finally { Pop-Location }
